package ama.storage;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.JsonNode;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
/** Actual finish() and actual evidence files; only rows() supplies public full-shape data, no retained SQL. */
class Task11B3BudgetFinalizationTest {
 @TempDir Path evidence;
 final com.fasterxml.jackson.databind.ObjectMapper json=Task11B2RuntimeFixture.JSON;
 Map<String,List<Map<String,Object>>> copy(Object rows){return json.convertValue(rows,new TypeReference<>(){});}
 class Fixture extends Task11B3BudgetDiagnosticIT {Map<String,List<Map<String,Object>>> observed;@Override Map<String,List<Map<String,Object>>> rows(){return observed;}}
 Fixture fixture(boolean changed)throws Exception {Path root=Path.of(System.getenv("AMA_TASK11_REPOSITORY_ROOT"));var frozen=json.readTree(Files.readAllBytes(root.resolve("artifacts/phase-b/b-remaining/task-11/b3-lifecycle-01/business-o4-closed.json")));assertEquals(19,frozen.size());var f=new Fixture();f.before=copy(frozen);f.observed=copy(frozen);if(changed)f.observed.get("meeting").getFirst().put("revision",14);var empty=json.createObjectNode();f.inputs=new Task11B3LifecycleInputs.Inputs(root,root.resolve(".superpowers/sdd/2026-10-23-ama-phase-b-remaining"),root.resolve(".tools/unused-offline"),evidence,empty,empty,empty,empty);f.databaseIdentityVerified=true;f.complete=true;return f;}
 void unqualified(JsonNode r){var facts=r.path("events").get(r.path("events").size()-1).path("facts");assertFalse(facts.path("diagnosisQualified").asBoolean(true));assertFalse(facts.path("committedSuccessorClaimQualified").asBoolean(true));}
 JsonNode result()throws Exception{return json.readTree(Files.readAllBytes(evidence.resolve("b3-budget-diagnostic-result.json")));}
 @Test void changedFinalRowsCannotPassEvenAfterTheSequenceCompleted()throws Exception {var f=fixture(true);assertThrows(AssertionError.class,()->f.finish(null));var r=result();assertEquals("PARTIAL_UNQUALIFIED",r.path("status").asText());assertFalse(r.path("finalRowsEqualInitial").asBoolean());assertTrue(r.has("cleanupFailureType"));unqualified(r);assertEquals(14,json.readTree(Files.readAllBytes(evidence.resolve("business-final-custody.json"))).path("meeting").get(0).path("revision").asInt());}
 @Test void changedFinalRowsArePreservedAndSuppressedUnderAnExistingPrimaryFailure()throws Exception {var f=fixture(true);var primary=new IllegalStateException("offline primary");assertDoesNotThrow(()->f.finish(primary));assertEquals(1,primary.getSuppressed().length);assertInstanceOf(AssertionError.class,primary.getSuppressed()[0]);assertEquals("PARTIAL_UNQUALIFIED",result().path("status").asText());assertFalse(result().path("finalRowsEqualInitial").asBoolean());unqualified(result());}
 @Test void equalActualFinalizationRemainsSuccessfulAndWritesBothCustodyFiles()throws Exception {var f=fixture(false);assertDoesNotThrow(()->f.finish(null));var r=result();assertEquals("PASS",r.path("status").asText());assertTrue(r.path("finalRowsEqualInitial").asBoolean());assertTrue(r.path("events").get(r.path("events").size()-1).path("facts").path("diagnosisQualified").asBoolean());assertFalse(r.path("events").get(r.path("events").size()-1).path("facts").path("committedSuccessorClaimQualified").asBoolean(true));assertEquals(json.valueToTree(f.before),json.readTree(Files.readAllBytes(evidence.resolve("business-final-custody.json"))));}
 @Test void finalReadFailureCannotYieldSuccess()throws Exception {var f=new Fixture(){@Override Map<String,List<Map<String,Object>>> rows(){throw new IllegalStateException("offline final read failed");}};var normal=fixture(false);f.inputs=normal.inputs;f.before=normal.before;f.databaseIdentityVerified=true;f.complete=true;assertThrows(IllegalStateException.class,()->f.finish(null));assertEquals("PARTIAL_UNQUALIFIED",result().path("status").asText());}
 void setup(Fixture target,Fixture normal){target.inputs=normal.inputs;target.before=normal.before;target.observed=normal.observed;target.databaseIdentityVerified=true;target.complete=true;}
 @Test void custodySaveFailureCannotYieldQualificationOrSuccess()throws Exception {var f=new Fixture(){@Override void save(String name,Object value,boolean exclusive)throws Exception {if(name.equals("business-final-custody.json"))throw new java.io.IOException("offline custody save failed");super.save(name,value,exclusive);}};setup(f,fixture(false));assertThrows(java.io.IOException.class,()->f.finish(null));assertEquals("PARTIAL_UNQUALIFIED",result().path("status").asText());unqualified(result());assertFalse(Files.exists(evidence.resolve("business-final-custody.json")));}
 @Test void closeFailureStillSavesFinalRowsAndAggregatesUnderPrimary()throws Exception {var f=new Fixture(){@Override void close(){throw new IllegalStateException("offline close failed");}};setup(f,fixture(false));var primary=new IllegalArgumentException("offline primary");assertDoesNotThrow(()->f.finish(primary));assertEquals(1,primary.getSuppressed().length);assertEquals("offline close failed",primary.getSuppressed()[0].getMessage());assertTrue(result().path("finalRowsEqualInitial").asBoolean());assertEquals("PARTIAL_UNQUALIFIED",result().path("status").asText());unqualified(result());assertTrue(Files.isRegularFile(evidence.resolve("business-final-custody.json")));}
 @Test void closeFailureWithoutPrimaryPropagatesAfterFinalCustody()throws Exception {var f=new Fixture(){@Override void close(){throw new IllegalStateException("offline close failed");}};setup(f,fixture(false));assertThrows(IllegalStateException.class,()->f.finish(null));assertEquals("PARTIAL_UNQUALIFIED",result().path("status").asText());unqualified(result());assertTrue(result().path("finalRowsEqualInitial").asBoolean());}

}
